begin;

-- Canonical, metadata-only company evidence registry (AGT-002 hotfix,
-- productive case 54190e51-15fb-46af-b0aa-8f13461a3110): psi_company_procurement_documents
-- was empty and psi_company_procurement_profile.supervigilancia_license carried a stale
-- free-text annotation, so AGT-002 asked a false question about a license that in fact
-- exists in the reviewed corporate corpus (Base Maestra provisional v0.2). This table
-- stores that corpus's per-entry metadata only — never a stored file, secret or signed
-- URL — with three explicitly separate status dimensions so a caller can never collapse
-- "the evidence exists" into "it is contractually applicable to a given case":
--   existence_status      — was this evidence reported as present in the reviewed corpus.
--   human_review_status   — has a human approved/rejected the entry (decision_humana*).
--   applicability_status  — does the entry apply to a specific tender/case (never implied
--                            by mere existence; starts and stays pending_case_validation
--                            until a case-specific human review sets it).
-- Versionable via (entry_id, version) with a single current=true row per entry_id, mirroring
-- psi_company_procurement_documents (026); no RPC is added here — this hotfix only ingests
-- the 17 currently active entries, it does not build a write path for future revisions.
create table if not exists public.psi_agt002_company_evidence_registry (
  id uuid primary key default gen_random_uuid(),
  entry_id text not null check (entry_id ~ '^[a-z][a-z0-9_]*$'),
  version integer not null check (version > 0),
  current boolean not null default true,
  document_class text not null check (nullif(btrim(document_class), '') is not null),
  classification text not null check (nullif(btrim(classification), '') is not null),
  estado_integracion text not null check (nullif(btrim(estado_integracion), '') is not null),
  sensibilidad text not null check (nullif(btrim(sensibilidad), '') is not null),
  source_reference text not null check (nullif(btrim(source_reference), '') is not null),
  item_id text check (item_id is null or nullif(btrim(item_id), '') is not null),
  duplicate_count integer check (duplicate_count is null or duplicate_count >= 0),
  hash text check (hash is null or hash ~ '^[0-9a-f]{64}$'),
  hash_contrastado_corpus_index boolean,
  zona_almacenamiento text not null check (nullif(btrim(zona_almacenamiento), '') is not null),
  utilidad_decisional text not null check (nullif(btrim(utilidad_decisional), '') is not null),
  accion_humana text not null check (nullif(btrim(accion_humana), '') is not null),
  human_gate text not null check (nullif(btrim(human_gate), '') is not null),
  control_de_uso text not null check (nullif(btrim(control_de_uso), '') is not null),
  -- Governance flags inherited from the manifest overlay (not per-entry in the
  -- source, but load-bearing for every entry): internal decision support only,
  -- no external submission authority, no automatic final approval.
  allowed_use jsonb not null default jsonb_build_object(
    'internal_decision_support', true,
    'external_submission_authority', false,
    'automatic_final_approval', false
  ) check (
    jsonb_typeof(allowed_use) = 'object'
    and allowed_use ? 'internal_decision_support'
    and allowed_use ? 'external_submission_authority'
    and allowed_use ? 'automatic_final_approval'
  ),
  metadata_only boolean not null,
  vigente_para_habilitacion boolean not null,
  existence_status text not null default 'reported' check (existence_status in ('verified', 'reported', 'not_verified')),
  human_review_status text not null default 'pending_human_review' check (human_review_status in ('pending_human_review', 'approved', 'rejected')),
  applicability_status text not null default 'pending_case_validation' check (applicability_status in ('pending_case_validation', 'applicable', 'not_applicable')),
  vigencia_text text not null check (nullif(btrim(vigencia_text), '') is not null),
  expiry date,
  decision_humana text check (decision_humana is null or nullif(btrim(decision_humana), '') is not null),
  decision_humana_fecha date,
  estado_posterior_decision text check (estado_posterior_decision is null or nullif(btrim(estado_posterior_decision), '') is not null),
  rollback_can_deactivate boolean not null default true,
  rollback_scope text not null default 'entry_id' check (rollback_scope = 'entry_id'),
  integration_active boolean not null default true,
  notes text,
  source_manifest_version text not null default 'v0.2-provisional-20260801' check (nullif(btrim(source_manifest_version), '') is not null),
  created_by uuid references public.psi_sales_profiles(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (entry_id, version),
  -- Existence can only ever be upgraded to 'verified' alongside a recorded human decision;
  -- mere presence in the ingested corpus can never auto-promote to verified/cumplido.
  check (existence_status <> 'verified' or (decision_humana is not null and decision_humana_fecha is not null)),
  check (human_review_status = 'pending_human_review' or (decision_humana is not null and decision_humana_fecha is not null)),
  check (applicability_status = 'pending_case_validation' or (
    human_review_status <> 'pending_human_review'
    and decision_humana is not null
    and decision_humana_fecha is not null
  ))
);

create unique index if not exists psi_agt002_company_evidence_registry_one_current_idx
  on public.psi_agt002_company_evidence_registry (entry_id)
  where current;

create index if not exists psi_agt002_company_evidence_registry_current_idx
  on public.psi_agt002_company_evidence_registry (entry_id, current, version desc);

drop trigger if exists trg_psi_agt002_company_evidence_registry_updated_at on public.psi_agt002_company_evidence_registry;
create trigger trg_psi_agt002_company_evidence_registry_updated_at before update on public.psi_agt002_company_evidence_registry
for each row execute function public.psi_sales_set_updated_at();

alter table public.psi_agt002_company_evidence_registry enable row level security;
revoke all on table public.psi_agt002_company_evidence_registry from public;
revoke all on table public.psi_agt002_company_evidence_registry from anon;
revoke all on table public.psi_agt002_company_evidence_registry from authenticated;
revoke all on table public.psi_agt002_company_evidence_registry from service_role;
grant select on table public.psi_agt002_company_evidence_registry to service_role;

-- Ingests the 17 currently active entries from the reviewed Base Maestra provisional
-- v0.2 (agt002_decision_knowledge_base_provisional_v0.2.json). Every row preserves the
-- source's own estado_integracion (INTEGRADO_PROVISIONAL_PENDIENTE_REVISION_HUMANA) and
-- is inserted with existence_status='reported' (never verified) and
-- applicability_status='pending_case_validation' (never applicable) — no entry is marked
-- as compliant/cumplido by this migration. expiry is populated only where the source's
-- "vigencia" text names an unambiguous end date (supervigilancia_operating_license,
-- rce_policy); every other entry's nuance stays in vigencia_text rather than being
-- guessed into a date. ON CONFLICT DO NOTHING keeps a re-run idempotent.
