  entry_id, version, current, document_class, classification, estado_integracion, sensibilidad,
  source_reference, item_id, duplicate_count, hash, hash_contrastado_corpus_index, zona_almacenamiento,
  utilidad_decisional, accion_humana, human_gate, control_de_uso, metadata_only, vigente_para_habilitacion,
  existence_status, human_review_status, applicability_status, vigencia_text, expiry,
  decision_humana, decision_humana_fecha, estado_posterior_decision,
  rollback_can_deactivate, rollback_scope, integration_active, notes
) values
